def where(tr, c, p):
    ids = []
    for line in LED.split('\n'):
        if re.search(r'\b%s %d:%d\b' % (tr, c, p), line):
            g = re.match(r'- (Sifrei Devarim \d+:\d+|Onkelos Deut \d+:\d+)', line)
            ids.append(g.group(1).replace('Sifrei Devarim ', '') if g else (line[:40] + '…'))
    return ids
